package com.careerorbit.service;
import com.careerorbit.ai.EmbeddingGateway;import com.careerorbit.mapper.*;import com.careerorbit.storage.ObjectStorageService;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import java.util.List;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class RagServiceTest {@Test void rrfDeduplicatesSameChunkAndPromotesHybridHit(){var service=new RagService(mock(KnowledgeDocumentMapper.class),mock(KnowledgeChunkMapper.class),mock(ObjectStorageService.class),mock(EmbeddingGateway.class),new ObjectMapper(),"http://localhost:9200","test",1,1);var shared=hit("shared");var lexical=hit("lexical");var semantic=hit("semantic");var result=service.rrf(List.of(shared,lexical),List.of(shared,semantic),10);assertThat(result).extracting(RagService.RagHit::chunkId).containsExactlyInAnyOrder("shared","lexical","semantic").doesNotHaveDuplicates();assertThat(result.get(0).chunkId()).isEqualTo("shared");assertThat(result.get(0).score()).isGreaterThan(result.get(1).score());}private RagService.RagHit hit(String id){return new RagService.RagHit(id,1,"title","content","cat","java","medium","source",1);}}
